import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.CXroN2RO.js";const o="/study/images/algorithms/quadtrees-and-octrees.svg",g=JSON.parse('{"title":"四分木と八分木 — 必要な場所だけ細かく分ける","description":"","frontmatter":{"title":"四分木と八分木 — 必要な場所だけ細かく分ける","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"二次元の領域を4分割、三次元の領域を8分割して木にし、境界をまたぐ物体の登録と範囲検索を追う。","aliases":["四分木","クアッドツリー","quadtree","八分木","オクツリー","octree","領域四分木","loose quadtree","loose octree","空間分割","AABB"],"verification":"Sametの領域分割の解説と移動物体の論文、OctoMapの公式資料、OGC 3D Tiles仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"algorithms/quadtrees-and-octrees.md","filePath":"algorithms/quadtrees-and-octrees.md"}'),n={name:"algorithms/quadtrees-and-octrees.md"};function d(i,e,l,h,p,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="四分木と八分木-—-必要な場所だけ細かく分ける" tabindex="-1">四分木と八分木 — 必要な場所だけ細かく分ける <a class="header-anchor" href="#四分木と八分木-—-必要な場所だけ細かく分ける" aria-label="Permalink to &quot;四分木と八分木 — 必要な場所だけ細かく分ける&quot;">​</a></h1><p>敵が広いマップの一部に集まっているとします。混み合った場所だけを細かく区切れば、広い空き地を同じ細かさで管理せずに、近くの敵を探せます。ここでは、二次元の領域を縦横の中央で分ける**四分木（クアッドツリー）<strong>と、三次元の領域を各軸の中央で分ける</strong>八分木（オクツリー）**を扱います。根が全体の領域を持ち、分割したノードがそれぞれ4個または8個の子領域を持ちます。必要な場所だけで分割を繰り返せます。<a href="https://www.cs.umd.edu/~hjs/pubs/Samettfcgc88-ocr.pdf" target="_blank" rel="noreferrer">Sametによる領域分割と点データの解説</a></p><h2 id="葉に記録するものを決める" tabindex="-1">葉に記録するものを決める <a class="header-anchor" href="#葉に記録するものを決める" aria-label="Permalink to &quot;葉に記録するものを決める&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>ノードや葉が持つもの</th><th>細かく分ける理由</th></tr></thead><tbody><tr><td>地形やボクセルの占有状態</td><td>領域の状態。例えば空き、占有、未観測</td><td>状態の違う場所を区別する。同じ状態が続く領域は1個の葉で表せる</td></tr><tr><td>点の位置を検索</td><td>点の座標やIDの一覧</td><td>点が集まる場所で、一度に調べる点を減らす</td></tr><tr><td>大きさのある物体を検索</td><td>物体IDと、その物体を包むAABB（軸に平行な境界箱）</td><td>箱が一つの子領域に収まるなら、その子を調べるときだけ検査する</td></tr></tbody></table><p>点を格納する方式では、分割線上の点をどちらの子に入れるかを決めます。例えば <code>x &gt;= 中央のx</code> なら右とすれば、同じ点を重複して登録せずに済みます。物体を登録するときは、中心の座標に加えて箱全体がどこまで広がるかを見ます。<a href="https://www.cs.umd.edu/~hjs/pubs/Samettfcgc88-ocr.pdf" target="_blank" rel="noreferrer">Sametによる点と領域の四分木</a></p><h2 id="境界をまたぐ物体は、収まる最も深いノードへ" tabindex="-1">境界をまたぐ物体は、収まる最も深いノードへ <a class="header-anchor" href="#境界をまたぐ物体は、収まる最も深いノードへ" aria-label="Permalink to &quot;境界をまたぐ物体は、収まる最も深いノードへ&quot;">​</a></h2><p>根から始めて、物体のAABB全体を含む子がちょうど一つなら、その子へ下ります。境界をまたいで一つに収まらない場合は、いまのノードに置きます。分割していない葉や深さの上限でも止めます。この方式では、各物体を1ノードにだけ登録します。箱の端が分割線に触れる場合も含め、登録と検索の境界ルールは揃えます。例えばこの例のように接触も交差に含めるなら、検索枠が境界に触れる子も調べます。<a href="https://www.cs.umd.edu/~hjs/pubs/sigmod13-header.pdf" target="_blank" rel="noreferrer">Sametらによる物体を収める領域の選び方</a></p><figure class="study-figure"><img src="'+o+`" alt="左のマップは根を4分割している。箱Aは上側の左右にまたがって根に登録される。右上だけにある破線の検索枠は箱Aの右端と箱Cに重なる。右の木では根のAを調べ、交差する右上の子でCを調べる。左上と左下、箱Bのある右下は調べない。" width="760" height="390" loading="lazy"><figcaption>検索枠は右上の子だけに入ります。根に置いたAも検索枠に重なるため、根と右上の両方を調べます。<a href="/study/images/algorithms/quadtrees-and-octrees.svg" target="_blank" rel="noopener noreferrer">配置と木の図を拡大</a></figcaption></figure><p>範囲検索では、検索枠と交差するノードに入ります。そこで子へ進む前に、そのノードに直接登録された箱も検査します。図では4個の箱のうち、根のAと右上のCの2個を検査すれば結果が得られます。次の擬似コードの結果は、検索枠とAABBが交差した物体です。円やポリゴンとの正確な交差が必要なら、候補に対して形状を使った判定を行います。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>範囲検索(ノード, 検索枠, 候補一覧):</span></span>
<span class="line"><span>    ノードの領域が検索枠と交差しなければ戻る</span></span>
<span class="line"><span>    ノードに直接登録された各物体について:</span></span>
<span class="line"><span>        物体のAABBが検索枠と交差するなら候補一覧に追加する</span></span>
<span class="line"><span>    存在する各子について:</span></span>
<span class="line"><span>        範囲検索(子, 検索枠, 候補一覧)</span></span></code></pre></div><h2 id="木が深くなり過ぎる場合と、物体が動く場合" tabindex="-1">木が深くなり過ぎる場合と、物体が動く場合 <a class="header-anchor" href="#木が深くなり過ぎる場合と、物体が動く場合" aria-label="Permalink to &quot;木が深くなり過ぎる場合と、物体が動く場合&quot;">​</a></h2><ul><li><strong>根の範囲</strong>は、登録する箱全体を含めます。根の外にも物体が移動するなら、根を広げるか、範囲外の物体を別の区画で管理する方針を決めます。</li><li><strong>分割を止める条件</strong>には、葉の件数だけでなく、最大深さや最小のセル幅を設けます。同じ座標に点が集中すると、細かく分けても同じ子に入り続けます。大きな箱が境界に重なると祖先に集中し、箱の検査は最悪で全件に及びます。</li><li><strong>移動の更新</strong>では、物体のAABBを更新し、いまの登録先が保持できる範囲を出たら移し替えます。子へ再配置できるようになった物体を下へ移すと、検索時の祖先の検査を減らせます。移動のたびに細かく移し替えるかは、検索と更新の頻度で決めます。</li></ul><p><strong>Loose quadtree / octree</strong> は、各セルの登録・検索に使う境界を広げる方式です。小さな移動なら広げた範囲に留まり、ノード間を移し替えずに済みます。一方、隣接するセルの広げた範囲は重なります。範囲検索では、物体を収めるために使った広い境界で交差を判定する必要があります。元の狭い境界で枝を省くと、セルからはみ出した物体を見落とすためです。<a href="https://www.cs.umd.edu/~hjs/pubs/sigmod13-header.pdf" target="_blank" rel="noreferrer">Sametらによる移動物体向けLoose quadtreeの論文</a></p><h2 id="八分木で三次元の空間を扱う" tabindex="-1">八分木で三次元の空間を扱う <a class="header-anchor" href="#八分木で三次元の空間を扱う" aria-label="Permalink to &quot;八分木で三次元の空間を扱う&quot;">​</a></h2><p>八分木は上下も分けるので、同じ水平位置にある違う高さの領域を区別できます。例えばOctoMapは三次元の占有地図を八分木で管理し、空きと占有に加えて未観測の空間も区別します。地形や建物のタイルを段階的に読み込む用途では、OGC 3D TilesのImplicit Tilingが四分木と八分木の両方を定義しています。<a href="https://octomap.github.io/octomap/doc/index" target="_blank" rel="noreferrer">OctoMapの占有地図の資料</a> · <a href="https://docs.ogc.org/cs/22-025r4/22-025r4.pdf" target="_blank" rel="noreferrer">OGC 3D Tiles仕様 §8</a></p><p><a href="/study/algorithms/uniform-grid-and-spatial-hash.html">均等グリッド</a>は全体を同じ幅で区切るので、セルの位置を座標から直接計算できます。四分木・八分木は場所によって分割の深さを変えられます。<a href="/study/algorithms/bounding-volume-hierarchies.html">BVH</a>の代表的な作り方では、物体をグループに分けて各グループを包む境界を作ります。子の境界同士は重なることがあります。どの方式も、検索時に領域や箱を調べる回数と、更新時に登録先を移し替える手間が分布や動き方で変わります。キーの大小関係で枝を選ぶ木は<a href="/study/algorithms/search-trees.html">二分探索木</a>で扱います。</p>`,16)])])}const m=a(n,[["render",d]]);export{g as __pageData,m as default};
